// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{})
}

// ServeMux is an abstraction of [http.ServeMux].
type ServeMux interface {
	HandleFunc(pattern string, handler func(http.ResponseWriter, *http.Request))
	http.Handler
}

type StdHTTPServerOptions struct {
	BaseURL          string
	BaseRouter       ServeMux
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, m ServeMux) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseRouter: m,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/node/info", wrapper.GetNodeInfo)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/node/blocks/latest", wrapper.GetLatestBlock)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/node/blocks/height/{height}", wrapper.GetBlockByHeight)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/node/blocks/hash/{blockHash}", wrapper.GetBlockByHash)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/node/transactions/{txHash}", wrapper.GetTransaction)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/node/fee-estimate", wrapper.GetFeeEstimate)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/node/mempool", wrapper.GetMempoolStats)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/node/regtest/generate-blocks", wrapper.GenerateBlocks)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/wallets", wrapper.ListWallets)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/wallets", wrapper.CreateWallet)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/wallets/restore/seed", wrapper.RestoreWalletFromSeed)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/wallets/restore/keys", wrapper.RestoreWalletFromKeys)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/wallets/{walletName}/open", wrapper.OpenWallet)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/wallets/{walletName}/close", wrapper.CloseWallet)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/wallets/{walletName}/status", wrapper.GetWalletStatus)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/wallets/{walletName}/balance", wrapper.GetWalletBalance)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/wallets/{walletName}/addresses", wrapper.ListWalletAddresses)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/wallets/{walletName}/addresses", wrapper.CreateWalletAddress)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/wallets/{walletName}/transfers", wrapper.ListWalletTransfers)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/wallets/{walletName}/transfers", wrapper.SendTransfer)

	return m
}

